import React, { Component } from "react";
import "./Contactus.css";


export default class Contactus extends Component {
    render() {
        return(

    <div className="content-container">
    <div className="rectangle">
    <h1><a href="/Contact Us" className="contact">Contact Us</a></h1>
    <p className="foryou">We are here for you!</p>
    <p className="na1">Name:</p>
    <input type="text" className="Name" placeholder="Name" required/>
    <p className="na1">Email:</p>
    <input type="text" className="Name" placeholder="Email" required/>

    <input className="Name"></input>
    <p className="na1">Message:</p>
    <input className="message"></input>
    <p className="sendmail">you can also send to our mail: TaiLink@gmail.com</p>
    <button type="button" className="button">send</button>
   </div>
   </div>



      );
    }     
}
